     7	import * as Expensicons from '@components/Icon/Expensicons';
     8	import MenuItem from '@components/MenuItem';
     9	import MenuItemWithTopDescription from '@components/MenuItemWithTopDescription';
    10	import OfflineWithFeedback from '@components/OfflineWithFeedback';
    11	import ScreenWrapper from '@components/ScreenWrapper';
    12	import Switch from '@components/Switch';
    13	import Text from '@components/Text';
    14	import TextLink from '@components/TextLink';
    15	import useLocalize from '@hooks/useLocalize';
    16	import usePermissions from '@hooks/usePermissions';
    17	import usePolicy from '@hooks/usePolicy';
    18	import useThemeStyles from '@hooks/useThemeStyles';
    19	import * as ErrorUtils from '@libs/ErrorUtils';
    20	import Navigation from '@libs/Navigation/Navigation';
    21	import * as PolicyUtils from '@libs/PolicyUtils';
    22	import type {SettingsNavigatorParamList} from '@navigation/types';
    23	import NotFoundPage from '@pages/ErrorPage/NotFoundPage';
    24	import AccessOrNotFoundWrapper from '@pages/workspace/AccessOrNotFoundWrapper';
    25	import {setWorkspaceTagEnabled} from '@userActions/Policy/Tag';
    26	import * as Tag from '@userActions/Policy/Tag';
    27	import CONST from '@src/CONST';
    28	import ONYXKEYS from '@src/ONYXKEYS';
    29	import ROUTES from '@src/ROUTES';
    30	import type SCREENS from '@src/SCREENS';
    31	
    32	type TagSettingsPageProps = StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.WORKSPACE.TAG_SETTINGS>;
    33	
    34	function TagSettingsPage({route, navigation}: TagSettingsPageProps) {
    35	    const [policyTags] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY_TAGS}${route.params.policyID}`);
    36	    const {orderWeight, policyID, tagName, backTo} = route.params;
    37	    const styles = useThemeStyles();
    38	    const {translate} = useLocalize();
    39	    const policyTag = useMemo(() => PolicyUtils.getTagList(policyTags, orderWeight), [policyTags, orderWeight]);
    40	    const policy = usePolicy(policyID);
    41	    const hasAccountingConnections = PolicyUtils.hasAccountingConnections(policy);
    42	    const {canUseCategoryAndTagApprovers} = usePermissions();
    43	    const [isDeleteTagModalOpen, setIsDeleteTagModalOpen] = React.useState(false);
    44	    const isQuickSettingsFlow = !!backTo;
    45	
    46	    const currentPolicyTag = policyTag.tags[tagName] ?? Object.values(policyTag.tags ?? {}).find((tag) => tag.previousTagName === tagName);
    47	
    48	    useEffect(() => {
    49	        if (currentPolicyTag?.name === tagName || !currentPolicyTag) {
    50	            return;
    51	        }
    52	        navigation.setParams({tagName: currentPolicyTag?.name});
    53	    }, [tagName, currentPolicyTag, navigation]);
    54	
    55	    if (!currentPolicyTag) {
    56	        return <NotFoundPage />;
    57	    }
    58	
    59	    const deleteTagAndHideModal = () => {
    60	        Tag.deletePolicyTags(policyID, [currentPolicyTag.name]);
    61	        setIsDeleteTagModalOpen(false);
    62	        Navigation.goBack(isQuickSettingsFlow ? ROUTES.SETTINGS_TAGS_ROOT.getRoute(policyID, backTo) : undefined);
    63	    };
    64	
    65	    const updateWorkspaceTagEnabled = (value: boolean) => {
    66	        setWorkspaceTagEnabled(policyID, {[currentPolicyTag.name]: {name: currentPolicyTag.name, enabled: value}}, policyTag.orderWeight);
    67	    };
    68	
    69	    const navigateToEditTag = () => {
    70	        Navigation.navigate(
    71	            isQuickSettingsFlow
    72	                ? ROUTES.SETTINGS_TAG_EDIT.getRoute(policyID, orderWeight, currentPolicyTag.name, backTo)
    73	                : ROUTES.WORKSPACE_TAG_EDIT.getRoute(policyID, orderWeight, currentPolicyTag.name),
    74	        );
    75	    };
    76	
    77	    const navigateToEditGlCode = () => {
    78	        if (!PolicyUtils.isControlPolicy(policy)) {
    79	            Navigation.navigate(
    80	                ROUTES.WORKSPACE_UPGRADE.getRoute(
    81	                    policyID,
    82	                    CONST.UPGRADE_FEATURE_INTRO_MAPPING.glCodes.alias,
    83	                    isQuickSettingsFlow
    84	                        ? ROUTES.SETTINGS_TAG_GL_CODE.getRoute(policy?.id ?? '', orderWeight, tagName, backTo)
    85	                        : ROUTES.WORKSPACE_TAG_GL_CODE.getRoute(policy?.id ?? '', orderWeight, tagName),
    86	                ),
    87	            );
    88	            return;
    89	        }
    90	        Navigation.navigate(
    91	            isQuickSettingsFlow
    92	                ? ROUTES.SETTINGS_TAG_GL_CODE.getRoute(policyID, orderWeight, currentPolicyTag.name, backTo)
    93	                : ROUTES.WORKSPACE_TAG_GL_CODE.getRoute(policyID, orderWeight, currentPolicyTag.name),
    94	        );
    95	    };
    96	
    97	    const navigateToEditTagApprover = () => {
    98	        Navigation.navigate(
    99	            isQuickSettingsFlow
   100	                ? ROUTES.SETTINGS_TAG_APPROVER.getRoute(policyID, orderWeight, currentPolicyTag.name, backTo)
   101	                : ROUTES.WORKSPACE_TAG_APPROVER.getRoute(policyID, orderWeight, currentPolicyTag.name),
   102	        );
   103	    };
   104	
   105	    const isThereAnyAccountingConnection = Object.keys(policy?.connections ?? {}).length !== 0;
   106	    const isMultiLevelTags = PolicyUtils.isMultiLevelTags(policyTags);
   107	    const tagApprover = PolicyUtils.getTagApproverRule(policyID, route.params.tagName)?.approver;
   108	
   109	    const shouldShowDeleteMenuItem = !isThereAnyAccountingConnection && !isMultiLevelTags;
   110	    const workflowApprovalsUnavailable = PolicyUtils.getWorkflowApprovalsUnavailable(policy);
   111	    const approverDisabled = !policy?.areWorkflowsEnabled || workflowApprovalsUnavailable;
   112	
   113	    return (
   114	        <AccessOrNotFoundWrapper
   115	            accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
   116	            policyID={policyID}
   117	            featureName={CONST.POLICY.MORE_FEATURES.ARE_TAGS_ENABLED}
   118	        >
   119	            <ScreenWrapper
   120	                includeSafeAreaPaddingBottom={false}
   121	                style={[styles.defaultModalContainer]}
   122	                testID={TagSettingsPage.displayName}
   123	            >
   124	                <HeaderWithBackButton
   125	                    title={PolicyUtils.getCleanedTagName(tagName)}
   126	                    shouldSetModalVisibility={false}
   127	                    onBackButtonPress={() => Navigation.goBack(isQuickSettingsFlow ? ROUTES.SETTINGS_TAGS_ROOT.getRoute(policyID, backTo) : undefined)}
   128	                />
   129	                <ConfirmModal
   130	                    title={translate('workspace.tags.deleteTag')}
   131	                    isVisible={isDeleteTagModalOpen}
   132	                    onConfirm={deleteTagAndHideModal}
   133	                    onCancel={() => setIsDeleteTagModalOpen(false)}
   134	                    shouldSetModalVisibility={false}
   135	                    prompt={translate('workspace.tags.deleteTagConfirmation')}
   136	                    confirmText={translate('common.delete')}
   137	                    cancelText={translate('common.cancel')}
   138	                    danger
   139	                />
   140	                <View style={styles.flexGrow1}>
   141	                    <OfflineWithFeedback
   142	                        errors={ErrorUtils.getLatestErrorMessageField(currentPolicyTag)}
   143	                        pendingAction={currentPolicyTag.pendingFields?.enabled}
   144	                        errorRowStyles={styles.mh5}
   145	                        onClose={() => Tag.clearPolicyTagErrors(policyID, tagName, orderWeight)}
   146	                    >
   147	                        <View style={[styles.mt2, styles.mh5]}>
   148	                            <View style={[styles.flexRow, styles.mb5, styles.mr2, styles.alignItemsCenter, styles.justifyContentBetween]}>
   149	                                <Text>{translate('workspace.tags.enableTag')}</Text>
   150	                                <Switch
   151	                                    isOn={currentPolicyTag.enabled}
   152	                                    accessibilityLabel={translate('workspace.tags.enableTag')}
   153	                                    onToggle={updateWorkspaceTagEnabled}
   154	                                />
   155	                            </View>
   156	                        </View>
   157	                    </OfflineWithFeedback>
   158	                    <OfflineWithFeedback pendingAction={currentPolicyTag.pendingFields?.name}>
   159	                        <MenuItemWithTopDescription
   160	                            title={PolicyUtils.getCleanedTagName(currentPolicyTag.name)}
   161	                            description={translate(`common.name`)}
   162	                            onPress={navigateToEditTag}
   163	                            shouldShowRightIcon
   164	                        />
   165	                    </OfflineWithFeedback>
   166	                    <OfflineWithFeedback pendingAction={currentPolicyTag.pendingFields?.['GL Code']}>
   167	                        <MenuItemWithTopDescription
   168	                            title={currentPolicyTag['GL Code']}
   169	                            description={translate(`workspace.tags.glCode`)}
   170	                            onPress={navigateToEditGlCode}
   171	                            iconRight={hasAccountingConnections ? Expensicons.Lock : undefined}
   172	                            interactive={!hasAccountingConnections}
   173	                            shouldShowRightIcon
   174	                        />
   175	                    </OfflineWithFeedback>
   176	
   177	                    {policy?.areRulesEnabled && canUseCategoryAndTagApprovers && (
   178	                        <>
   179	                            <View style={[styles.mh5, styles.mv3, styles.pt3, styles.borderTop]}>
   180	                                <Text style={[styles.textNormal, styles.textStrong, styles.mv3]}>{translate('workspace.tags.tagRules')}</Text>
   181	                            </View>
   182	                            <MenuItemWithTopDescription
   183	                                title={tagApprover ?? ''}
   184	                                description={translate(`workspace.tags.approverDescription`)}
   185	                                onPress={navigateToEditTagApprover}
   186	                                shouldShowRightIcon
   187	                                disabled={approverDisabled}
   188	                            />
   189	                            {approverDisabled && (
   190	                                <Text style={[styles.flexRow, styles.alignItemsCenter, styles.mv2, styles.mh5]}>
   191	                                    <Text style={[styles.textLabel, styles.colorMuted]}>{translate('workspace.rules.categoryRules.goTo')}</Text>{' '}
   192	                                    <TextLink
   193	                                        style={[styles.link, styles.label]}
   194	                                        onPress={() => Navigation.navigate(ROUTES.WORKSPACE_MORE_FEATURES.getRoute(policyID))}
   195	                                    >
   196	                                        {translate('workspace.common.moreFeatures')}
   197	                                    </TextLink>{' '}
   198	                                    <Text style={[styles.textLabel, styles.colorMuted]}>{translate('workspace.rules.categoryRules.andEnableWorkflows')}</Text>
   199	                                </Text>
   200	                            )}
   201	                        </>
   202	                    )}
   203	
   204	                    {shouldShowDeleteMenuItem && (
   205	                        <MenuItem
   206	                            icon={Expensicons.Trashcan}
   207	                            title={translate('common.delete')}
   208	                            onPress={() => setIsDeleteTagModalOpen(true)}
   209	                        />
   210	                    )}
   211	                </View>
   212	            </ScreenWrapper>
   213	        </AccessOrNotFoundWrapper>
   214	    );
   215	}
   216	
   217	TagSettingsPage.displayName = 'TagSettingsPage';
   218	
   219	export default TagSettingsPage;
